components.css:
.ds-node-sample {
  --canvas: #1e1f22; --panel: #2b2d30; --raised: #393b40; --text: #dfe1e5;
  --muted: #9da0a8; --border: #393b40; --control-border: #4e5157;
  --accent: #3574f0; --accent-text: #ffffff; --selected: #2e436e; --hover: #393b40;
  --good: #89cc8e; --warning: #f2c55c; --error: #eb938d;
  --good-bg: #253627; --warning-bg: #3d3223; --error-bg: #402929;
  --toolbar: #2b2d30; --toolbar-text: #dfe1e5; --toolbar-muted: #b4b8bf;
  --toolbar-selected: #2e436e; --toolbar-hover: #393b40; --rail: #2b2d30;
  --editor: #1e1f22; --editor-text: #dfe1e5; --code-green: #6aab73;
  --code-blue: #56a8f5; --code-orange: #cf8e6d; --code-muted: #9da0a8;
  --line: #393b40; --scrim: #00000066; --scroll-thumb: #5a5d63;
  --nav-field: #2b2d30; --tools-field: #2b2d30; --primary-hover: #467ff2;
  --font-ui: "Segoe UI", "Microsoft YaHei UI", "PingFang SC", system-ui, sans-serif;
  --font-code: "JetBrains Mono", Consolas, "SFMono-Regular", "Liberation Mono", monospace;
  --stroke: 1px; --weight: 500; color-scheme: dark;
}
.ds-theme-light {
  --canvas: #ffffff; --panel: #f7f8fa; --raised: #ffffff; --text: #27282e;
  --muted: #5a5d6b; --border: #dfe1e5; --control-border: #c9ccd6;
  --selected: #d4e2ff; --hover: #ebecf0; --good: #1e6b33; --warning: #a46704;
  --error: #ad2b38; --good-bg: #e3f7e7; --warning-bg: #fff5db; --error-bg: #ffebec;
  --toolbar: #27282e; --toolbar-text: #ebecf0; --toolbar-muted: #c9ccd6;
  --toolbar-selected: #383a42; --toolbar-hover: #494b57; --rail: #f7f8fa;
  --editor: #ffffff; --editor-text: #27282e; --code-green: #067d17;
  --code-blue: #0033b3; --code-orange: #9e4b00; --code-muted: #6c707e;
  --line: #ebecf0; --scrim: #27282e42; --scroll-thumb: #a8adbd;
  --nav-field: #f7f8fa; --tools-field: #f7f8fa; color-scheme: light;
}
.ds-theme-dopamine {
  --canvas: #fbf1e8; --panel: #fffbe6; --raised: #fffef5; --text: #20211f;
  --muted: #585c52; --border: #20211f; --control-border: #20211f;
  --accent: #5346a6; --accent-text: #20211f; --selected: #ffde75; --hover: #fff0bc;
  --good: #176b4f; --warning: #7a4a08; --error: #a12c38;
  --good-bg: #d5f1e5; --warning-bg: #fff0bc; --error-bg: #ffd7cc;
  --toolbar: #ffb7cf; --toolbar-text: #20211f; --toolbar-muted: #585c52;
  --toolbar-selected: #ffde75; --toolbar-hover: #ffd3e2; --rail: #fbf1e8;
  --editor: #fffbe6; --editor-text: #20211f; --code-green: #176b4f;
  --code-blue: #5346a6; --code-orange: #7a4a08; --code-muted: #585c52;
  --line: #eadcc1; --scrim: #20211f55; --scroll-thumb: #92907b;
  --nav-field: #ffb7cf; --tools-field: #d5f1e5; --primary-hover: #ffe795;
  --stroke: 2px; --weight: 600; color-scheme: light;
}
.ds-gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}.ds-node-sample{padding:12px;color:var(--text);background:var(--canvas);font:13px/1.5 var(--font-ui);min-width:0}.ds-theme-name{font-size:12px;color:var(--muted);margin:0 0 12px}.ds-node-sample button{font:inherit;color:inherit;box-sizing:border-box;cursor:pointer}.ds-node-sample svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none}.ds-theme-dark .connection-node.selected{--muted:#b4b8bf}.ds-node-sample .connection-node:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.grow { flex: 1; min-width: 0; }
.dot { width: 6px; height: 6px; border-radius: 50%; background: var(--muted); display: inline-block; flex: none; }
.dot.connected, .dot.running { background: var(--good); }
.dot.failed, .dot.unhealthy { background: var(--error); }
.dot.connecting { background: var(--warning); }
.status { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.connection-node { position: relative; z-index: 1; display: flex; gap: 8px; align-items: center; width: 100%; min-width: 0; min-height: 52px; text-align: left; padding: 5px 10px; border: var(--stroke) solid var(--control-border); border-radius: 6px; background: var(--canvas); font-weight: 400; }
.connection-node:hover { background: var(--hover); }
.connection-node.on-route { border-color: var(--accent); }
.connection-node.selected { background: var(--selected); border-color: var(--accent); }
.node-icon { display: flex; align-items: center; justify-content: center; width: 20px; height: 20px; color: var(--muted); flex: none; }
.node-icon svg { width: 18px; height: 18px; }
.on-route .node-icon { color: var(--text); }
.node-content { flex: 1; min-width: 0; }
.node-heading { display: flex; align-items: center; gap: 6px; }
.node-heading strong { min-width: 0; font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.node-protocol { flex: none; font-size: 10px; color: var(--muted); border: 1px solid var(--control-border); padding: 0 4px; border-radius: 3px; }
.node-heading .status, .node-context-label { flex: none; font-size: 11px; color: var(--muted); white-space: nowrap; }
.node-meta { display: flex; align-items: baseline; gap: 10px; margin-top: 1px; }
.node-endpoint { display: block; min-width: 0; flex: 1; color: var(--muted); font: 11px/1.6 var(--font-code); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.node-tags { display: flex; flex: none; gap: 5px; max-width: 45%; overflow: hidden; }
.node-tags > span { min-width: 0; font-size: 11px; line-height: 1.6; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.node-tags > span + span { border-left: 1px solid var(--control-border); padding-left: 5px; }
.context .node-icon { color: var(--muted); }
[data-density="compact"] .connection-node { min-height: 48px; padding-top: 3px; padding-bottom: 3px; }
